package dev.zomboid.gore;
import java.util.*;import dev.zomboid.gore.fast.FastReflection;
public final class CorpseCollect {
 static final Map<Object,Iterator<Map.Entry<Long,Object>>> CURSORS=new WeakHashMap<>();static final Set<String> WARNED=new HashSet<>();
 static Object call(Object o,String n,Object...a){return FastReflection.call(o,n,a);}static Object get(Object o,String n){return FastReflection.get(o,n);}static boolean yes(Object o){return Boolean.TRUE.equals(o);}static double num(Object o){return ((Number)o).doubleValue();}
 public static void tick(Object event){try{Object level=call(event,"getLevel");if(yes(get(level,"isClientSide"))||((Number)call(level,"getGameTime")).longValue()%20!=0)return;for(Object player:(Iterable<?>)call(level,"players"))if(get(player,"containerMenu")!=get(player,"inventoryMenu"))return;int queries=0;
 for(Object e:(Iterable<?>)call(level,"getAllEntities")){if(!e.getClass().getName().equals("de.maxhenkel.corpse.entities.CorpseEntity")||queries>=8)continue;Object death=call(e,"getDeath");@SuppressWarnings("unchecked") List<Object> inventory=(List<Object>)call(death,"getMainInventory");@SuppressWarnings("unchecked") List<Object> additional=(List<Object>)call(death,"getAdditionalItems");collect(level,call(e,"blockPosition"),inventory,null,additional);queries++;}
 Class<?> remains;try{remains=FastReflection.type("dev.zomboid.remains.ZombieRemainsLoot");}catch(IllegalStateException absent){return;}Object data=call(remains,"data",level);@SuppressWarnings("unchecked") Map<Long,Object> map=(Map<Long,Object>)get(data,"corpses");Iterator<Map.Entry<Long,Object>> it=CURSORS.get(level);if(it==null||!it.hasNext()){it=map.entrySet().iterator();CURSORS.put(level,it);}for(int tested=0;tested<64&&queries<16&&it.hasNext();tested++){Map.Entry<Long,Object> entry=it.next();Object pos=call(FastReflection.type("net.minecraft.core.BlockPos"),"of",entry.getKey());if(!yes(call(level,"hasChunkAt",pos)))continue;Object corpse=entry.getValue();if(!yes(call(remains,"remains",call(level,"getBlockState",pos))))continue;if(!get(corpse,"block").equals(call(remains,"blockId",call(level,"getBlockState",pos))))continue;Object inventory=get(corpse,"inventory");if(collect(level,pos,null,inventory,null)>0)call(data,"setDirty");queries++;}
 }catch(ConcurrentModificationException retry){CURSORS.clear();}catch(Throwable e){if(WARNED.add(e.toString()))System.err.println("[zomboid-gore] corpse collection: "+e);}}
 static int collect(Object level,Object pos,List<Object> list,Object container,List<Object> expandable){double x=num(call(pos,"getX"))+.5,y=num(call(pos,"getY"))+.2,z=num(call(pos,"getZ"))+.5;Object box=FastReflection.make("net.minecraft.world.phys.AABB",x-3,y-1,z-3,x+3,y+2,z+3);Class<?> itemType=FastReflection.type("net.minecraft.world.entity.item.ItemEntity");java.util.function.Predicate<Object> predicate=e->!yes(call(e,"isRemoved"))&&((Number)get(e,"tickCount")).intValue()>=100;List<?> items=(List<?>)call(level,"getEntitiesOfClass",itemType,box,predicate);int count=0,processed=0;for(Object item:items){if(processed++>=32)break;double dx=num(call(item,"getX"))-x,dy=num(call(item,"getY"))-y,dz=num(call(item,"getZ"))-z;if(dx*dx+dy*dy+dz*dz>9||Math.abs(dy)>1.5)continue;if(!clear(level,item,pos,x,y,z))continue;Object stack=call(call(item,"getItem"),"copy");int before=((Number)call(stack,"getCount")).intValue();if(container!=null&&container.getClass().getName().equals("dev.zomboid.remains.expand.ExpandedStorage"))call(container,"absorb",stack);else insert(stack,list,container);if(expandable!=null&&!yes(call(stack,"isEmpty")))insertGrowing(stack,expandable);int remaining=((Number)call(stack,"getCount")).intValue();if(remaining==before)continue;if(remaining==0)call(item,"discard");else call(item,"setItem",stack);count++;}if(count>0&&container!=null)call(container,"setChanged");return count;}
 static boolean clear(Object level,Object item,Object pos,double x,double y,double z){Object from=call(call(item,"position"),"add",0d,.1d,0d),to=FastReflection.make("net.minecraft.world.phys.Vec3",x,y,z);Object ctx=FastReflection.make("net.minecraft.world.level.ClipContext",from,to,get(FastReflection.type("net.minecraft.world.level.ClipContext$Block"),"COLLIDER"),get(FastReflection.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),item);Object hit=call(level,"clip",ctx);return call(hit,"getType").toString().equals("MISS")||pos.equals(call(hit,"getBlockPos"));}
 static void insertGrowing(Object stack,List<Object> list){insert(stack,list,null);while(!yes(call(stack,"isEmpty"))){int amount=Math.min(((Number)call(stack,"getCount")).intValue(),((Number)call(stack,"getMaxStackSize")).intValue());if(amount<=0)return;Object copy=call(stack,"copy");call(copy,"setCount",amount);list.add(copy);call(stack,"shrink",amount);}}
 static void insert(Object stack,List<Object> list,Object container){int size=list!=null?list.size():((Number)call(container,"getContainerSize")).intValue();Class<?> stacks=FastReflection.type("net.minecraft.world.item.ItemStack");for(int pass=0;pass<2;pass++)for(int slot=0;slot<size&&!yes(call(stack,"isEmpty"));slot++){Object existing=list!=null?list.get(slot):call(container,"getItem",slot);boolean empty=yes(call(existing,"isEmpty"));if(pass==0&&(empty||!yes(call(stacks,"isSameItemSameComponents",existing,stack))))continue;if(pass==1&&!empty)continue;int limit=((Number)call(stack,"getMaxStackSize")).intValue();if(container!=null)limit=Math.min(limit,((Number)call(container,"getMaxStackSize")).intValue());int amount=Math.min(((Number)call(stack,"getCount")).intValue(),limit-(empty?0:((Number)call(existing,"getCount")).intValue()));if(amount<=0)continue;Object replacement=empty?call(stack,"copy"):call(existing,"copy");call(replacement,"setCount",(empty?0:((Number)call(existing,"getCount")).intValue())+amount);if(list!=null)list.set(slot,replacement);else call(container,"setItem",slot,replacement);call(stack,"shrink",amount);}}
}
